import { Routes } from "react-router-dom";

import { Route } from "react-router-dom";
import RequireAuth from "../auth/guards/RequireAuth";

export default function ProtectedRoutes(){
    return (
        <Routes>
            <Route path="/" 
            element={<RequireAuth>
                {/* <Home /> */}
                <div>Home</div>
            </RequireAuth>} />
        </Routes>
    );
}